import { NextResponse } from 'next/server';
import { timingSafeEqual } from 'crypto';
import { documentFilename, renderDocumentPdf } from '@/lib/documents/pdf';
import { getDocumentByNumber } from '@/lib/documents/store';

/**
 * The customer's own copy, reached by the link in their email or WhatsApp
 * message. No sign-in, so the token is the whole of the protection:
 *
 *  - it is a random uuid generated by the database, never derived from the
 *    document number, so knowing one tells you nothing about the other;
 *  - the comparison is timing-safe;
 *  - only the ORIGINAL is ever served here. The duplicate is the office copy
 *    and there is no version of this route that should hand it out.
 *
 * The same shape as the existing /order/[orderNumber] guard, deliberately —
 * one pattern for "a customer reaching their own record without an account".
 */
export const dynamic = 'force-dynamic';

function tokenMatches(supplied: string | null, expected: string): boolean {
  if (!supplied) return false;
  const a = Buffer.from(supplied);
  const b = Buffer.from(expected);
  if (a.length !== b.length) return false;
  return timingSafeEqual(a, b);
}

export async function GET(request: Request, { params }: { params: { docNumber: string } }) {
  const document = await getDocumentByNumber(params.docNumber);
  const token = new URL(request.url).searchParams.get('token');

  // One answer for "no such document" and "wrong token", so the route cannot
  // be used to work out which numbers exist.
  if (!document || !tokenMatches(token, document.accessToken)) {
    return NextResponse.json({ ok: false, error: 'Not found' }, { status: 404 });
  }

  const bytes = await renderDocumentPdf(document, 'original');

  return new NextResponse(Buffer.from(bytes), {
    headers: {
      'Content-Type': 'application/pdf',
      'Content-Disposition': `inline; filename="${documentFilename(document, 'original')}"`,
      'Cache-Control': 'private, no-store',
      // Belt and braces: a link that leaks into a referrer header is a link
      // that leaks the token with it.
      'Referrer-Policy': 'no-referrer',
      'X-Robots-Tag': 'noindex, nofollow',
    },
  });
}
